const $ = s => document.querySelector(s);
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const kg = n => Number(n || 0).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const rs = p => '₹' + (Number(p || 0) / 100).toLocaleString('en-IN', { maximumFractionDigits: 2 });
const dateFmt = d => new Date(d).toLocaleString('en-IN', { dateStyle: 'medium', timeStyle: 'short' });
const activeStates = ['reserved', 'delivered'];
let comparisonLotId = 'LOT-002';
let state = null, view = 'overview', modal = null, selectedCaseId = 'CASE-001', toastTimer = null, message = null, loading = false, loginError = '';
let authScreen='signin', authNotice='', mobileMenu=false;
const initialAuth=new URLSearchParams(window.location.search);
if(['verify','reset'].includes(initialAuth.get('auth'))){authScreen=initialAuth.get('auth');}

async function request(path, method = 'GET', data) {
 const response = await fetch('/api' + path, { method, headers: data ? { 'Content-Type': 'application/json' } : {}, body: data ? JSON.stringify(data) : undefined, credentials: 'same-origin' });
 const payload = await response.json().catch(() => ({}));
 if (!response.ok) throw Error(payload.error || `Request failed (${response.status})`);
 return payload;
}
async function refresh() {
 try { state = await request('/bootstrap'); if(state.user.role==='buyer')view='portal'; render(); }
 catch (e) { state = null; render(); }
}
function notify(text, bad = false) {message = {text,bad}; renderToast(); clearTimeout(toastTimer); toastTimer = setTimeout(()=>{message=null; renderToast();},4500);}
function renderToast(){let holder=$('#toasts');if(holder)holder.innerHTML=message?`<div class="toast ${message.bad?'bad':''}">${esc(message.text)}</div>`:'';}
const brand = `<span class="brandmark" aria-hidden="true"></span>agrova`;
const names = {overview:'Overview',lots:'Lots & quality',orders:'Buyer orders',fulfillment:'Supply gap resolver',recovery:'Recovery case',economics:'Net recovery',settlement:'Settlement & review',ledger:'Farmer ledger',activity:'Activity log',farmers:'Farmers',portal:'Buyer portal'};
const icons = {overview:'◫',lots:'▧',orders:'▤',fulfillment:'↕',recovery:'↗',economics:'₹',settlement:'◎',ledger:'▣',activity:'≡',farmers:'♙'};
function isManager(){return state?.user?.role==='manager';}
function offersForLot(id){return (state?.offers||[]).filter(x=>x.lot_id===id);}
function reservedForLot(id){return offersForLot(id).filter(x=>activeStates.includes(x.status)).reduce((s,x)=>s+x.quantity_kg,0)+(state?.original_allocations||[]).filter(x=>x.lot_id===id&&['reserved','dispatched'].includes(x.status)).reduce((s,x)=>s+x.quantity_kg,0);}
function reservedForOrder(id){return state.offers.filter(x=>x.order_id===id&&activeStates.includes(x.status)).reduce((s,x)=>s+x.quantity_kg,0)+(state?.original_allocations||[]).filter(x=>x.order_id===id&&['reserved','dispatched'].includes(x.status)).reduce((s,x)=>s+x.quantity_kg,0);}
function available(lot){return Math.max(0,Math.round((lot.quantity_kg-reservedForLot(lot.id))*1000)/1000);}
function eligible(order){return state.lots.filter(l=>l.grade===order.grade && l.crop.toLowerCase()===order.crop.toLowerCase()&&l.safety==='cleared').reduce((s,l)=>s+available(l),0);}
function shortage(order){return Math.max(0,order.quantity_kg-reservedForOrder(order.id)-eligible(order));}
function feasible(lot,order){return lot.safety==='cleared'&&lot.crop.toLowerCase()===order.crop.toLowerCase()&&lot.grade===order.grade&&order.availability==='accepting'? Math.max(0,Math.min(available(lot),order.quantity_kg-reservedForOrder(order.id))):0;}
function caseInfo(){return state.cases.find(x=>x.id===selectedCaseId)??state.cases[0]??null;}
function lotById(id){return state.lots.find(x=>x.id===id);}
function orderById(id){return state.orders.find(x=>x.id===id);}
function offerById(id){return state.offers.find(x=>x.id===id);}
function deliverByOffer(id){return state.deliveries.find(x=>x.offer_id===id);}
function getContext(){const c=caseInfo();return c?{c,lot:lotById(c.lot_id),orig:orderById(c.original_order_id),offers:state.offers.filter(x=>x.case_id===c.id)}:null;}
function latestOffer(offers){return offers.find(x=>x.status!=='cancelled')??null;}
function values() {
 const received=state.lots.reduce((s,l)=>s+l.quantity_kg,0);
 const reserved=state.offers.filter(x=>activeStates.includes(x.status)).reduce((s,x)=>s+x.quantity_kg,0);
 const disputes=state.deliveries.filter(x=>['needs_review','more_evidence'].includes(x.settlement_status));
 const pending=disputes.reduce((s,x)=>s+x.reconciliation.disputed_paise,0);
 const original=state.orders.find(o=>o.is_original);
 return {received,reserved,pending,disputes:disputes.length,shortage:original?shortage(original):0};
}
function chip(txt,cls=''){return `<span class="pill ${cls}">${esc(txt)}</span>`;}
function metric(label,val,unit,desc){return `<div class="metric"><div class="k">${esc(label)}</div><div><span class="v num">${esc(val)}</span><span class="unit">${esc(unit||'')}</span></div><div class="desc">${esc(desc||'')}</div></div>`;}
function heading(eyebrow,title,desc,buttons=''){return `<div class="eyebrow">${esc(eyebrow)}</div><div class="section-head"><div><h1 class="h1">${esc(title)}</h1><p class="lead" style="margin-bottom:0">${esc(desc)}</p></div>${buttons}</div>`;}
function navHTML(){const navs=isManager()?['overview','farmers','lots','orders','fulfillment','recovery','economics','settlement','ledger','activity']:['portal'];return `<aside class="sidebar"><div class="brand">${brand}</div><div class="tiny-caps sidebar-caption">OPERATIONS WORKSPACE</div><div class="center-label">COLLECTION CENTRE</div><div class="location">❖ &nbsp;${esc(state.user.fpo_name||'Green Valley FPO')}</div><div class="location-sub">${state.is_demo?'Demo Centre 01':'Private FPO workspace'}</div><nav class="nav" aria-label="Main navigation">${navs.map(n=>`<button class="nav-btn ${view===n?'active':''}" data-action="view" data-view="${n}"><span class="nav-ico">${icons[n]||'◫'}</span><span class="nav-text">${names[n]}</span>${n==='recovery'?`<span class="count-badge">${state.cases.length}</span>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><span class="dot"></span> Shared server workspace<br><div class="team">Team INNOVATRIX<br>Recovery, Sourcing & Settlement OS</div><button class="signout" data-action="logout">Sign out ↗</button></div></aside>`;}
function mobileNavigation(){
 const navs=isManager()?['overview','farmers','lots','orders','fulfillment','recovery','economics','settlement','ledger','activity']:['portal'];
 const primary=isManager()?['overview','farmers','lots','recovery']:['portal'];
 const item=n=>`<button class="mobile-nav-button ${view===n?'active':''}" data-action="view" data-view="${n}" aria-label="${esc(names[n])}"><span aria-hidden="true">${icons[n]||'▧'}</span><small>${esc(names[n])}</small></button>`;
 const extras=navs.filter(n=>!primary.includes(n));
 return `<nav class="mobile-nav" aria-label="Mobile navigation">${primary.map(item).join('')}<button class="mobile-nav-button" data-action="mobile-more" aria-expanded="${mobileMenu}" aria-label="More pages"><span>☰</span><small>More</small></button></nav>${mobileMenu?`<div class="mobile-drawer"><div class="mobile-drawer-heading"><strong>All workspaces</strong><button data-action="mobile-more" aria-label="Close menu">✕</button></div><div class="mobile-drawer-grid">${extras.map(n=>`<button data-action="view" data-view="${n}">${icons[n]||'▧'} &nbsp;${esc(names[n])}</button>`).join('')}<button data-action="logout">Sign out ↗</button></div></div>`:''}`;
}
function chrome(){return `<div class="shell">${navHTML()}<div class="page"><header class="topbar"><div class="crumb">Workspace <span>/</span> ${esc(names[view]||'Agrova')}</div><div class="top-actions"><span class="demo-tag">● &nbsp;${state.is_demo?'ILLUSTRATIVE DATA':'PRIVATE FPO WORKSPACE'}</span>${isManager()&&state.is_demo?`<button class="btn small" data-action="reset">↻ Reset demo</button>`:''}<button class="profile-pill" data-action="logout" title="Click to sign out">${esc(state.user.display_name)} &nbsp;↗</button></div></header><main class="content">${renderView()}<footer class="footer"><span>Agrova / Built for decisions that protect every harvest.</span><span>${state.is_demo?'Tomato pilot · Illustrative buyers & prices':'Private FPO workspace · Enter your own lots & orders'} · Payments not processed</span></footer></main></div>${mobileNavigation()}${modal?modalHTML():''}<div class="toasts" id="toasts"></div></div>`;}
function overview(){const k=values(),ctx=getContext();const top=ctx?.orig;const lots=state.lots;const caseLine=ctx?`${ctx.c.id}: ${ctx.orig.buyer_name} needs ${kg(ctx.orig.quantity_kg)} kg Grade ${ctx.orig.grade}. Eligible inventory covers ${kg(eligible(ctx.orig))} kg. Inspect the gap and find a feasible next move.`:'Create a recovery case from a lot and an unfulfilled order.';
return `${heading('YOUR HARVEST, ACCOUNTED FOR','Good decisions. Better outcomes.','From buyer mismatch to evidence-backed settlement, every lot stays traceable.')}<div class="hero"><div><div class="eyebrow">RECOVERY INTELLIGENCE</div><h2>Every mismatch deserves<br>a better next move.</h2><p>${esc(caseLine)}</p><button class="btn lime" data-action="view" data-view="recovery">Open recovery case ↗</button><button class="btn hero-secondary" data-action="view" data-view="fulfillment">Resolve original shortage →</button></div><div class="hero-graphic"><span class="brandmark"></span></div></div><section class="metrics">${metric('Received produce',kg(k.received),'kg',`${state.lots.length} farmer lots · All crops`)}${metric('Original order shortage',kg(k.shortage),'kg',top?`Grade ${top.grade} requirement`:'No original order')}${metric('Recovery committed',kg(k.reserved),'kg','Reserved + delivered allocation')}${metric('Amount under review',rs(k.pending),'',`${k.disputes} discrepancies awaiting review`)}</section><div class="grid-2"><div class="panel"><div class="rowbetween"><h3>Produce at a glance</h3>${chip('Live inventory')}</div><div class="lines">${lots.slice(0,8).map(l=>`<div class="line"><div class="farmer-block"><div class="avatar">${esc(l.farmer[0])}</div><div><strong>${esc(l.farmer)}</strong><br><small>${esc(l.id)} · ${esc(l.crop)} · Grade ${esc(l.grade)}</small></div></div><div style="text-align:right"><strong>${kg(available(l))} kg available</strong><br><small>${kg(reservedForLot(l.id))} kg allocated</small></div>${chip(l.safety==='cleared'?'Cleared':l.safety,l.safety==='cleared'?'':'warn')}</div>`).join('')}</div><div class="button-row"><button class="btn" data-action="view" data-view="lots">Manage lots →</button><button class="btn light" data-action="open" data-modal="lot">+ Create lot</button></div></div><div class="panel"><div class="rowbetween"><h3>Operational alerts</h3>${chip('Actionable')}</div><div class="lines">${top?`<div class="line"><span><strong>${esc(top.buyer_name)}</strong><br><small>Original order gap</small></span>${chip(`${kg(shortage(top))} kg short`,'warn')}</div>`:''}${ctx?`<div class="line"><span><strong>Recovery stock</strong><br><small>${esc(ctx.lot.farmer)} · ${esc(ctx.lot.id)}</small></span>${chip(`${kg(available(ctx.lot))} kg available`)}</div>`:''}${k.disputes?`<div class="line"><span><strong>Evidence mismatch</strong><br><small>Human review required</small></span>${chip(`${k.disputes} cases`,'danger')}</div>`:`<div class="line"><span><strong>Settlement checks</strong><br><small>Awaiting evidence or delivery</small></span>${chip('No open dispute')}</div>`}</div><div class="note">An alternative sale does not resolve an unrelated original buyer shortage. Both outcomes remain visible.</div><button class="btn" data-action="view" data-view="recovery">Review connected case →</button></div></div>`;}
function farmersPage(){const registered=state.farmers||[];
 return `${heading('FARMER ONBOARDING','Farmer directory','Register farmer profiles once; associate their new crop lots using a unique farmer ID.',`<button class="btn primary" data-action="open" data-modal="farmer">+ Register farmer</button>`)}<section class="metrics">${metric('Registered farmers',registered.length,'','Private to this FPO workspace')}${metric('Crop lots',state.lots.length,'','Each lot tracks inspection separately')}</section><div class="panel"><h3>Registered farmers</h3>${registered.length?`<div class="tablewrap"><table class="data-table"><thead><tr><th>Farmer ID</th><th>Farmer name</th><th>Mobile (private)</th><th>Linked lots</th></tr></thead><tbody>${registered.map(f=>`<tr><td><strong>${esc(f.id)}</strong></td><td>${esc(f.name)}</td><td>${esc(f.phone||'Not provided')}</td><td>${state.lots.filter(l=>l.farmer_id===f.id).length}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No registered farmers yet</h3><p>Add your first farmer, then record their crop lot.</p><button class="btn primary" data-action="open" data-modal="farmer">Register first farmer →</button></div>'}<div class="note">This is FPO-assisted onboarding. Farmer self-login and SMS OTP are not connected in this release. Do not upload real personal data into a public demo deployment.</div></div><div class="button-row"><button class="btn" data-action="view" data-view="lots">Manage crop lots →</button></div>`;
}
function lotsPage(){return `${heading('INBOUND PRODUCE','Lots & quality','Record received produce, inspection grade, and safety status. Reserved/delivered lots are protected.',`<button class="btn primary" data-action="open" data-modal="lot">+ Add farmer lot</button>`)}<div class="panel"><div class="tablewrap"><table class="data-table"><thead><tr><th>Lot / farmer</th><th>Crop</th><th>Received</th><th>Available</th><th>Grade</th><th>Safety</th><th>Actions</th></tr></thead><tbody>${state.lots.map(l=>`<tr><td><strong>${esc(l.farmer)}</strong><div class="fine">${esc(l.id)} · revision ${l.version}</div></td><td>${esc(l.crop)}</td><td>${kg(l.quantity_kg)} kg</td><td><strong>${kg(available(l))} kg</strong><div class="fine">${kg(reservedForLot(l.id))} kg locked/shipped</div></td><td>${chip('Grade '+l.grade)}</td><td>${chip(l.safety==='cleared'?'Cleared':l.safety,l.safety==='cleared'?'':'warn')}</td><td><button class="btn small" data-action="open" data-modal="edit-lot" data-id="${l.id}">${reservedForLot(l.id)?'🔒':'Edit'}</button><button class="btn small" data-action="open" data-modal="passport" data-id="${l.id}">Passport</button></td></tr>`).join('')}</tbody></table></div><div class="note">Safety holds exclude produce from matching. A grade mismatch is not the same as unsafe produce. Once stock is reserved or delivered, its grade and safety cannot be silently overwritten.</div></div><div class="button-row"><button class="btn" data-action="view" data-view="orders">View buyer requirements →</button><button class="btn" data-action="open" data-modal="case">+ New recovery case</button></div>`;}
function orderCard(o){const original=!!o.is_original;const elig=eligible(o);const allocated=reservedForOrder(o.id);return `<div class="panel order-card"><div class="order-title"><h3>${esc(o.buyer_name)}</h3>${chip(original?'Original order':'Recovery buyer',original?'warn':'')}</div><div class="text-xs muted">${esc(o.id)} · ${esc(o.crop)} · Grade ${esc(o.grade)} ${original?'only':'accepted'}</div><form data-form="edit-order" data-id="${o.id}"><div class="field"><label>${original?'Required quantity':'Maximum buyer demand'} (kg)</label><input type="number" name="quantity_kg" min="0.001" step="0.001" value="${o.quantity_kg}" required></div><div class="field"><label>Agreed price (₹/kg)</label><input type="number" name="price_inr" step="0.01" min="0" value="${o.price_paise/100}" required></div><div class="fields-grid">${field('transport_inr','Estimated transport cost (₹)','number',(o.transport_paise||0)/100,'min="0" step="0.01" required')}${field('handling_inr','Estimated handling cost (₹)','number',(o.handling_paise||0)/100,'min="0" step="0.01" required')}</div><div class="field"><label>Buyer availability</label><select name="availability"><option value="accepting" ${o.availability==='accepting'?'selected':''}>Accepting offers</option><option value="paused" ${o.availability==='paused'?'selected':''}>Not accepting</option></select></div><div class="stat-line"><span>Available eligible Grade ${o.grade}</span><strong>${kg(elig)} kg</strong></div><div class="stat-line"><span>Reserved / delivered</span><strong>${kg(allocated)} kg</strong></div><div class="stat-line"><span>${original?'Remaining shortage':'Supply gap (eligibility only)'}</span><strong>${kg(shortage(o))} kg</strong></div><div class="note">${original?`GRADE CHECK: Only inspected, cleared Grade ${o.grade} stock counts. Mismatched grades cannot fulfil this order.`:`Eligibility checks crop, grade, safety, demand, and available stock. Pickup and distance are illustrative assumptions, not live-verified.`}</div><button class="btn primary" type="submit">Save & rerun matching</button></form></div>`;}
function ordersPage(){return `${heading('PROCUREMENT','Buyer orders','Edit buyer demand and rerun eligibility. Matching uses inspected, cleared stock only.',`<button class="btn primary" data-action="open" data-modal="order">+ Add buyer order</button>`)}<div class="cards-grid">${state.orders.map(orderCard).join('')}</div><div class="button-row"><button class="btn" data-action="view" data-view="recovery">Explore recovery options →</button></div>`;}
function steps(ctx){const ofr=latestOffer(ctx.offers);let n=ofr?.status==='delivered'?4:ofr?.status==='reserved'?3:ofr?2:1;return `<div class="stepper">${['Mismatch detected','Offer & reservation','Delivery inspection','Settlement review'].map((x,i)=>`<div class="step ${i+1===n?'active':i+1<n?'done':''}"><span class="step-num">0${i+1}</span>${x}</div>`).join('')}</div>`;}
function recovery(){const ctx=getContext();if(!ctx)return `${heading('CROP RECOVERY','Recovery cases','Make a new case to connect a mismatched lot with its original buyer order.')}<div class="empty"><h3>No cases yet</h3><button class="btn primary" data-action="open" data-modal="case">Create case</button></div>`;
const {c,lot,orig,offers}=ctx;const active=latestOffer(offers);const candidates=state.orders.filter(o=>!o.is_original&&o.id!==orig.id).map(o=>({order:o,max:feasible(lot,o)})).sort((a,b)=>b.max-a.max||b.order.price_paise-a.order.price_paise);
const proposal=active?.quantity_kg ?? (candidates[0]?.max || 0);const primary=active?orderById(active.order_id):candidates.find(x=>x.max>0)?.order;
const delivery=active?deliverByOffer(active.id):null;
const remaining=available(lot);const headline=active?`${kg(active.quantity_kg)} kg · ${active.status}`:`${kg(proposal)} kg · available to offer`;
const explain=delivery?`${lot.farmer} जी, आपकी ${kg(active.quantity_kg)} किलो ग्रेड ${lot.grade} फसल भेजी गई। निरीक्षण में ${kg(delivery.accepted_kg)} किलो स्वीकार हुई। तय दर पर ${rs(delivery.accepted_kg*active.agreed_price_paise)} बनते हैं (कटौतियों से पहले)। खरीदार के रिकॉर्ड की पुष्टि बाकी हो सकती है।`:`${lot.farmer} जी, आपकी ${kg(lot.quantity_kg)} किलो फसल ग्रेड ${lot.grade} है। ${orig.buyer_name} को ग्रेड ${orig.grade} चाहिए। ${primary?primary.buyer_name+' को '+kg(proposal)+' किलो का वैकल्पिक प्रस्ताव दिया जा सकता है।':'अभी कोई उपयुक्त वैकल्पिक खरीदार उपलब्ध नहीं है।'} ${kg(remaining)} किलो अभी रिज़र्व/डिलीवर नहीं हुई है।`;
return `<div class="utility-bar"><div class="eyebrow" style="margin:0">${esc(c.id)} · ${esc(lot.crop.toUpperCase())} RECOVERY</div><div class="tab-tools"><select id="case-switch" aria-label="Select case" class="btn small">${state.cases.map(x=>`<option value="${x.id}" ${c.id===x.id?'selected':''}>${esc(x.id)}</option>`).join('')}</select><button class="btn small" data-action="open" data-modal="case">+ Case</button></div></div><h1 class="h1">Recover this lot. Track every outcome.</h1><p class="lead">Explain the mismatch. Recover a feasible sale. Keep every unresolved quantity visible.</p>${steps(ctx)}<section class="metrics">${metric('Original buyer shortage',kg(shortage(orig)),'kg',`${orig.buyer_name} · remains open`)}${metric(`${lot.farmer.split(' ')[0]}'s received lot`,kg(lot.quantity_kg),'kg',`${lot.id} · Grade ${lot.grade}`)}${metric('Recovery offer / allocation',kg(active?.quantity_kg??proposal),'kg',active?`${active.status} · ${orderById(active.order_id)?.buyer_name||''}`:'Proposed · not confirmed')}${metric('Recovery lot remaining',kg(remaining),'kg','Does not include already reserved/delivered produce')}</section><div class="recommend"><div class="panel recommend-card"><div class="rowbetween"><h3>Compatible buyer recommendation</h3>${chip(candidates.some(x=>x.max>0)?'Buyer available':'No compatible buyer',candidates.some(x=>x.max>0)?'':'warn')}</div>${candidates.length?candidates.map(({order:o,max})=>`<div class="buyer-option ${max>0?'good':''}"><div class="rowbetween"><strong>${esc(o.buyer_name)}</strong>${chip(max>0?`${kg(max)} kg feasible`:'Ineligible',max>0?'':'warn')}</div><div class="meta">Grade ${esc(o.grade)} · ${rs(o.price_paise)}/kg · Max demand ${kg(o.quantity_kg)} kg · ${o.availability==='accepting'?'Accepting offers':'Paused'}</div><div class="meta">${max>0?`Estimated maximum gross: ${rs(max*o.price_paise)}. Safety, crop and grade passed.`:`${lot.safety!=='cleared'?'Lot is not safety cleared.':lot.grade!==o.grade?'Grade mismatch.':o.availability!=='accepting'?'Buyer unavailable.':'No free compatible quantity.'}`}</div></div>`).join(''):'<div class="empty">No alternative buyer demand configured.</div>'}${!candidates.some(x=>x.max>0)?`<div class="note warning">No eligible recovery buyer. Do not invent demand, prices or availability. The case remains unresolved.</div>`:''}<div class="button-row"><button class="btn primary" data-action="open" data-modal="offer" ${!candidates.some(x=>x.max>0)?'disabled':''}>+ Send recovery offer</button><button class="btn" data-action="view" data-view="orders">Edit buyer demand →</button></div></div><div class="panel"><h3>Farmer-facing explanation (Hindi)</h3><div class="text-sm muted" style="margin:-13px 0 21px">${esc(lot.farmer)} · ${esc(lot.id)}</div><div class="explain" id="hindi-explanation">${esc(explain)}</div><div class="button-row"><button class="btn" data-action="speak">▷ Read Hindi explanation</button></div><h4 style="margin-top:26px">Two separate outcomes</h4><ol class="list-bullets"><li>Recover Grade ${lot.grade} stock through a compatible buyer.</li><li>Source <strong>${kg(shortage(orig))} kg</strong> eligible Grade ${orig.grade} for ${esc(orig.buyer_name)}.</li></ol><p class="help">Recovery does not automatically fulfil the original buyer's order. Rejected quantities require custody review before re-entering inventory.</p></div></div><div class="panel" style="margin-top:22px"><div class="rowbetween"><h3>Recovery offers & reservations</h3>${chip(`${offers.length} total`)}</div>${offers.length?offers.map(o=>offerLine(o)).join(''):'<div class="empty"><h3>No offer sent yet</h3>Pick an eligible buyer to start the buyer-consent → FPO-reservation lifecycle.</div>'}</div>`;}
function offerLine(o){const buyer=orderById(o.order_id);const delivery=deliverByOffer(o.id);const status=o.status;return `<div class="buyer-option"><div class="rowbetween"><div><strong>${esc(o.id)} · ${esc(buyer?.buyer_name||'Buyer')}</strong><div class="meta">${kg(o.quantity_kg)} kg × ${rs(o.agreed_price_paise)}/kg = ${rs(o.quantity_kg*o.agreed_price_paise)}${o.buyer_accepted_demo?' · DEMO acceptance':''}</div></div>${chip(status.replaceAll('_',' '),['cancelled'].includes(status)?'warn':status==='delivered'?'':'neutral')}</div><div class="button-row">${status==='offered'?`<button class="btn small" data-action="demo-accept" data-id="${o.id}">Simulate buyer acceptance</button><button class="btn small warn" data-action="cancel" data-id="${o.id}">Cancel</button>`:''}${status==='accepted'?`<button class="btn primary small" data-action="reserve" data-id="${o.id}">Confirm FPO reservation</button><button class="btn small warn" data-action="cancel" data-id="${o.id}">Cancel</button>`:''}${status==='reserved'?`<button class="btn primary small" data-action="open" data-modal="delivery" data-id="${o.id}">Record delivery inspection →</button><button class="btn small warn" data-action="cancel" data-id="${o.id}">Cancel reservation</button>`:''}${status==='delivered'?`<button class="btn small" data-action="view" data-view="settlement">Review ${esc(delivery?.id||'delivery')} →</button>`:''}</div></div>`;}
function settlement(){const deliveries=state.deliveries;let selected=deliveries[0];if(window.__deliveryChoice){selected=deliveries.find(d=>d.id===window.__deliveryChoice)||selected;}
if(!selected)return `${heading('EVIDENCE & RECONCILIATION','Settlement & review','AI reads evidence. Rules calculate. A manager decides.')}<div class="empty"><h3>Delivery inspection not recorded</h3><p>Reserve an alternative offer and record accepted/rejected quantities to start the settlement evidence chain.</p><button class="btn primary" data-action="view" data-view="recovery">Open recovery case →</button></div>`;
const o=offerById(selected.offer_id);const lot=lotById(o.lot_id);const buyer=orderById(o.order_id);const r=selected.reconciliation;const inspected=selected.evidence.filter(e=>e.kind==='inspection');const statements=selected.evidence.filter(e=>e.kind==='buyer');const disputed=r.difference_kg!=null&&r.difference_kg!==0;
return `${heading('EVIDENCE & RECONCILIATION','Settlement & review','AI proposes extracted fields. Verified quantities go into deterministic calculations. Final review is human.',`<button class="btn primary" data-action="open" data-modal="upload" data-id="${selected.id}">+ Upload evidence</button>`)}<div class="rowbetween" style="margin-bottom:23px"><div class="help">${esc(selected.id)} · ${esc(lot.farmer)} · ${esc(buyer.buyer_name)} · ${kg(selected.delivered_kg)} kg delivered</div>${chip(selected.settlement_status.replaceAll('_',' '),['needs_review','more_evidence'].includes(selected.settlement_status)?'danger':selected.settlement_status==='reviewed_unpaid'?'':'warn')}</div><div class="metrics">${metric('Delivery inspected',kg(selected.delivered_kg),'kg','Confirmed shipment quantity')}${metric('Inspection accepted',kg(r.inspection_kg),'kg','Provisional inspection basis')}${metric('Buyer states',r.buyer_kg===null?'—':kg(r.buyer_kg),r.buyer_kg===null?'':'kg',r.buyer_kg===null?'Upload & verify buyer statement':'Verified buyer record')}${metric('Under review',rs(['needs_review','more_evidence'].includes(selected.settlement_status)?r.disputed_paise:0),'',`Agreed rate ${rs(o.agreed_price_paise)}/kg`)}</div><div class="review-grid"><div class="panel"><div class="rowbetween"><h3>1. Evidence documents</h3><button class="btn small" data-action="open" data-modal="upload" data-id="${selected.id}">+ Add file</button></div><div class="help">Supported: TXT / PDF / PNG / JPG / WebP (5 MB max). Private server-side storage. Extraction does not imply verification.</div><h4 style="margin:21px 0 10px">Inspection evidence</h4>${inspected.length?inspected.map(docLine).join(''):`<div class="note warning">No inspection receipt uploaded. Delivery inspection fields are available but have no document attached yet.</div>`}<h4 style="margin:23px 0 10px">Buyer statements</h4>${statements.length?statements.map(docLine).join(''):`<div class="note warning">No buyer statement verified. Discrepancy cannot be calculated until a buyer record is confirmed.</div>`}<div class="note">AI may misread text. Missing values stay blank. Managers must verify actual fields against each source document.</div></div><div class="panel"><h3>2. Reconciliation engine</h3><div class="kv"><span>Inspection accepted</span><strong>${kg(r.inspection_kg)} kg</strong></div><div class="kv"><span>Buyer accepted</span><strong>${r.buyer_kg===null?'Awaiting document':kg(r.buyer_kg)+' kg'}</strong></div><div class="kv"><span>Agreed price</span><strong>${rs(o.agreed_price_paise)}/kg</strong></div><div class="kv"><span>Inspection provisional payable</span><strong>${rs(r.inspection_payable_paise)}</strong></div><div class="kv"><span>Buyer reported value</span><strong>${r.buyer_reported_paise===null?'—':rs(r.buyer_reported_paise)}</strong></div><div class="eyebrow" style="margin:27px 0 9px">AMOUNT REQUIRING REVIEW</div><div class="review-amount num">${r.buyer_kg===null?'—':rs(r.disputed_paise)}</div><div class="help">${r.buyer_kg===null?'Upload and verify both documents.':`${kg(Math.abs(r.difference_kg))} kg difference × ${rs(o.agreed_price_paise)}/kg. ${r.difference_kg<0?'Buyer quantity exceeds inspection.':'Inspection quantity exceeds buyer statement.'}`}</div>${selected.inspection_conflict?`<div class="note error">Inspection receipt disagrees with the originally recorded delivery inspection. Resolve this conflict before closing.</div>`:''}<div class="note ${disputed?'warning':''}">${selected.latest_review?`Latest human decision: ${esc(selected.latest_review.decision.replaceAll('_',' '))}. Payment remains UNPAID.`:disputed?'Mismatch flagged — not evidence of fraud. An authorized reviewer must examine the source documents.':'No confirmed buyer mismatch yet. Payment remains UNPAID.'}</div><h3 style="margin-top:30px">3. Human review</h3>${selected.latest_review?`<p class="help"><strong>${esc(selected.latest_review.decision.replaceAll('_',' '))}</strong> · ${dateFmt(selected.latest_review.created_at)}<br>${esc(selected.latest_review.note)}</p>`:''}<button class="btn primary" data-action="open" data-modal="review" data-id="${selected.id}">Record reviewer decision →</button><p class="help">No payments are executed by this prototype. Approval is never automatic.</p></div></div>`;}
function docLine(doc){const status=doc.verified?'Manager verified':doc.proposed?'Extracted · needs confirmation':'Needs extraction/review';return `<div class="doc"><div style="min-width:0"><strong>▤ ${esc(doc.file_name)}</strong><small>${esc(doc.id)} · ${dateFmt(doc.created_at)} · ${esc(doc.engine)}<br>${esc(status)} ${doc.verified?`· ${kg(doc.verified.accepted_kg)} kg accepted`:''}</small><div class="button-row"><a class="btn small" target="_blank" rel="noopener" href="/api/evidence/${doc.id}/file">View file ↗</a>${!doc.verified?`<button class="btn small" data-action="extract" data-id="${doc.id}" ${!state.ai_enabled&&doc.mime!=='text/plain'?'disabled title="Gemini API key required for PDFs/images"':''}>${state.ai_enabled?'AI extract':'Parse text'}</button>`:''}<button class="btn small primary" data-action="open" data-modal="verify" data-id="${doc.id}">${doc.verified?'Revise verification':'Verify fields'}</button></div></div></div>`;}
function activity(){return `${heading('TRACEABILITY','Activity log','Append-only records for lots, offers, inspection evidence, and human decisions.')}<div class="panel"><h3>Case event history</h3><div class="timeline">${state.events.map(e=>`<div class="timeline-item"><strong>${esc(e.action.replaceAll('_',' '))}</strong><div class="meta">${esc(e.ref)} · ${esc(e.actor_name)} · ${dateFmt(e.created_at)}</div><p>${esc(e.detail)}</p></div>`).join('')}</div></div>`;}
function buyerPortal(){return `${heading('BUYER PORTAL','Incoming purchase offers',`Signed in as ${state.user.display_name}. Review offers addressed to your company.`)}<div class="metrics">${metric('Buyer orders',state.orders.length,'', 'Your company only')}${metric('Awaiting response',state.offers.filter(o=>o.status==='offered').length,'', 'Action required')}${metric('Accepted / reserved',state.offers.filter(o=>['accepted','reserved','delivered'].includes(o.status)).length,'','Your matched offers')}${metric('Completed deliveries',state.offers.filter(o=>o.status==='delivered').length,'','Settlement handled by FPO')}</div><div class="panel"><h3>Your offers</h3>${state.offers.length?state.offers.map(o=>`<div class="buyer-option"><div class="rowbetween"><div><strong>${esc(o.id)} · ${esc(state.orders.find(x=>x.id===o.order_id)?.buyer_name||'Buyer')}</strong><div class="meta">${kg(o.quantity_kg)} kg · ${rs(o.agreed_price_paise)}/kg · ${rs(o.quantity_kg*o.agreed_price_paise)} potential gross</div></div>${chip(o.status)}</div>${o.status==='offered'?`<div class="button-row"><button class="btn primary small" data-action="buyer-accept" data-id="${o.id}">Accept offer →</button></div>`:''}</div>`).join(''):'<div class="empty"><h3>No offers yet</h3>The FPO manager can propose a compatible lot from the recovery workspace.</div>'}<div class="note">An accepted offer is not yet reserved stock. The FPO manager must confirm the reservation separately.</div></div>`;}

function v3Net(qty,order){return Math.round(qty*order.price_paise)-(order.transport_paise||0)-(order.handling_paise||0);}
function fulfillmentPage(){
 const orig=state.orders.find(o=>o.is_original);
 if(!orig)return heading('SUPPLY GAP RESOLVER','Original order fulfillment','Create an original buyer order to see supply gaps.');
 const free=eligible(orig),reserved=reservedForOrder(orig.id),gap=shortage(orig),quotes=(state.suppliers||[]).filter(s=>s.original_order_id===orig.id),totalReceived=quotes.filter(q=>q.status==='received').reduce((s,q)=>s+(q.received_kg||0),0);
 return `${heading('SMART FULFILLMENT','Supply gap resolver','Resolve the original buyer shortage with inspected partner supply, then allocate stock. A quote is not delivered inventory.',`<button class="btn primary" data-action="open" data-modal="source-quote">+ Add supplier quote</button>`)}
 <div class="note warning">DEMO SUPPLIER NETWORK: Partner offers and confirmations here are illustrative/manual, not authenticated live FPO inventory. Only physically received and inspected stock enters eligible inventory.</div>
 <section class="metrics">${metric('Buyer order',kg(orig.quantity_kg),'kg',orig.buyer_name+' · Grade '+orig.grade)}${metric('Allocated to order',kg(reserved),'kg','Reserved/dispatched, not buyer-accepted')}${metric('Eligible but unallocated',kg(free),'kg','Inspected and safety cleared')}${metric('Current uncovered gap',kg(gap),'kg','Updates after supplier receiving')}</section>
 <div class="panel" style="margin-bottom:20px"><div class="rowbetween"><h3>Original order coverage</h3>${chip(gap===0?'Supply coverable':'Shortage requires sourcing',gap>0?'warn':'')}</div><p class="help">${kg(reserved)} kg is committed + ${kg(free)} kg eligible and uncommitted. ${kg(gap)} kg still needs eligible supply. Even full allocation means dispatch pending, not a completed or paid order.</p><div class="chartbar"><span style="width:${Math.max(0,Math.min(100,(orig.quantity_kg-gap)/orig.quantity_kg*100))}%"></span></div><div class="button-row"><button class="btn primary" data-action="auto-allocate" data-id="${orig.id}">Allocate currently eligible stock →</button><button class="btn" data-action="view" data-view="orders">Buyer requirements →</button></div></div>
 <div class="panel"><div class="rowbetween"><h3>Partner supplier quotations</h3>${chip(quotes.length+' quotes')}</div><div class="supply-grid">${quotes.map(q=>`<div class="supply-card"><div class="rowbetween"><div><strong>${esc(q.supplier_name)}</strong><div class="fine">${esc(q.id)} · ${esc(q.location)} · ${esc(q.source_reference.replaceAll('_',' ').toLowerCase())}</div></div>${chip(q.status.replaceAll('_',' '),q.status==='quoted'?'warn':'')}</div><div class="supply-meta"><span>Offer <strong>${kg(q.offered_kg)} kg</strong></span><span>Grade <strong>${esc(q.grade)}</strong></span><span>Rate <strong>${rs(q.unit_price_paise)}/kg</strong></span></div><div class="text-xs muted">Est. source cost ${rs(q.offered_kg*q.unit_price_paise+q.transport_paise+q.handling_paise)} including transport/handling</div>${q.status==='received'?`<div class="note">Received ${kg(q.received_kg)} kg as ${esc(q.received_lot_id)} · Inspection determines eligibility.</div>`:''}<div class="button-row">${q.status==='quoted'?`<button class="btn primary small" data-action="source-confirm" data-id="${q.id}">Simulate supplier confirmation</button><button class="btn small warn" data-action="source-cancel" data-id="${q.id}">Cancel</button>`:''}${q.status==='demo_confirmed'?`<button class="btn primary small" data-action="open" data-modal="source-receive" data-id="${q.id}">Receive & inspect →</button><button class="btn small warn" data-action="source-cancel" data-id="${q.id}">Cancel</button>`:''}</div></div>`).join('')||'<div class="empty">No partner quotes yet. Add a verified/manual sourcing offer to begin.</div>'}</div></div>
 <div class="panel" style="margin-top:20px"><div class="rowbetween"><h3>Original order stock allocations</h3>${chip('Dispatch pending')}</div>${(state.original_allocations||[]).filter(a=>a.order_id===orig.id).length?`<div class="tablewrap"><table class="data-table"><thead><tr><th>Allocation</th><th>Source lot</th><th>Quantity</th><th>Status</th><th>Action</th></tr></thead><tbody>${state.original_allocations.filter(a=>a.order_id===orig.id).map(a=>`<tr><td>${esc(a.id)}</td><td>${esc(a.lot_id)} · ${esc(lotById(a.lot_id)?.farmer||'')}</td><td>${kg(a.quantity_kg)} kg</td><td>${chip(a.status)}</td><td>${a.status==='reserved'?`<button class="btn small" data-action="original-dispatch" data-id="${a.id}">Record dispatch</button><button class="btn small warn" data-action="original-cancel" data-id="${a.id}">Release</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No original order stock has been reserved. Allocate available Grade A lots first.</div>'}<div class="note">Procurement quote → supplier confirmation → receiving inspection → stock allocation → dispatch. Buyer receipt/acceptance for the original order is not simulated as complete.</div></div>`;
}
function economicsPage(){const lot=lotById(comparisonLotId)||state.lots.find(l=>l.grade==='B')||state.lots[0];if(!lot)return '';
 const opts=state.orders.filter(o=>!o.is_original).map(o=>{const qty=feasible(lot,o);const gross=Math.round(qty*o.price_paise);const costs=(o.transport_paise||0)+(o.handling_paise||0);return {o,qty,gross,costs,net:gross-costs};}).filter(x=>x.qty>0).sort((a,b)=>b.net-a.net);
 return `${heading('NET RECOVERY OPTIMIZER','Compare actual economics','Filter by grade, safety, crop and demand first. Then compare estimated net realization after transport and handling.',`<button class="btn" data-action="view" data-view="orders">Edit buyer rates & costs →</button>`)}<div class="panel" style="margin-bottom:20px"><div class="rowbetween"><div><h3>Compare buyers for this lot</h3><div class="help">No live price, transport or buyer-availability verification. Edit values on Buyer orders and rerun.</div></div><select class="btn" id="economics-lot" aria-label="Select lot">${state.lots.map(l=>`<option value="${l.id}" ${lot.id===l.id?'selected':''}>${esc(l.id)} · ${esc(l.farmer)} · ${esc(l.grade)}</option>`).join('')}</select></div>${metric('Uncommitted stock',kg(available(lot)),'kg',lot.safety+' · Grade '+lot.grade)}</div>
 <div class="cards-grid">${opts.map((r,i)=>`<div class="panel"><div class="rowbetween"><h3>${esc(r.o.buyer_name)}</h3>${i===0?chip('Highest estimated net'):chip('Eligible')}</div><div class="fine">${esc(r.o.id)} · ${kg(r.qty)} kg Grade ${lot.grade}</div><div class="kv"><span>Gross sale value</span><strong>${rs(r.gross)}</strong></div><div class="kv"><span>Estimated transport</span><span>−${rs(r.o.transport_paise)}</span></div><div class="kv"><span>Estimated handling</span><span>−${rs(r.o.handling_paise)}</span></div><div class="rowbetween" style="margin-top:20px"><div><div class="help">Estimated net realization</div><div class="calc-value">${rs(r.net)}</div></div>${chip(`${rs(Math.round(r.net/Math.max(r.qty,.001)))}/kg net`)}</div></div>`).join('')||'<div class="empty">No feasible buyers. Add an alternative buyer with compatible grade and available demand.</div>'}</div><div class="note warning">Negative net values are possible; they indicate estimated charges exceed gross revenue. This comparison is advisory—not a confirmed transaction or payment.</div>`;
}
function ledgerPage(){const farmers=state.lots.map(l=>{const delivered=state.deliveries.filter(d=>offerById(d.offer_id)?.lot_id===l.id);const inspection=delivered.reduce((s,d)=>s+d.reconciliation.inspection_payable_paise,0);const disputed=delivered.filter(d=>['needs_review','more_evidence'].includes(d.settlement_status)).reduce((s,d)=>s+d.reconciliation.disputed_paise,0);return {l,delivered,inspection,disputed};});
 return `${heading('FARMER TRANSPARENCY','Farmer settlement ledger','Provisional inspection-based amounts and disputed differences, grouped by source lot. Real payment processing is not connected.')}<section class="metrics">${metric('Farmers / source lots',farmers.length,'','Separate farmer or partner-source records')}${metric('Inspected deliveries',state.deliveries.length,'','Alternative buyer deliveries')}${metric('Provisional value',rs(farmers.reduce((s,x)=>s+x.inspection,0)),'','Before any recorded settlement transfer')}${metric('Pending discrepancy',rs(farmers.reduce((s,x)=>s+x.disputed,0)),'','Awaiting evidence / reviewer action')}</section><div class="panel"><h3>Farmer-level traceability</h3><div class="tablewrap"><table class="data-table"><thead><tr><th>Farmer / lot</th><th>Original received</th><th>Recovery deliveries</th><th>Provisional payable</th><th>Unresolved discrepancy</th><th>Paid</th></tr></thead><tbody>${farmers.map(({l,delivered,inspection,disputed})=>`<tr><td><strong>${esc(l.farmer)}</strong><div class="fine">${esc(l.id)} · Grade ${esc(l.grade)}</div></td><td>${kg(l.quantity_kg)} kg</td><td>${kg(delivered.reduce((s,d)=>s+d.delivered_kg,0))} kg</td><td>${rs(inspection)}</td><td>${rs(disputed)}</td><td>${chip('Not integrated','warn')}</td></tr>`).join('')}</tbody></table></div><div class="note">This ledger does not invent payments. Figures show inspection-based gross provisional value; any buyer-statement mismatch remains separately visible. Receipts, buyer acceptance and bank transfers must be verified before paid status is recorded.</div></div>`;
}
function renderView(){if(!isManager())return buyerPortal();return ({overview,farmers:farmersPage,lots:lotsPage,orders:ordersPage,fulfillment:fulfillmentPage,recovery,economics:economicsPage,settlement,ledger:ledgerPage,activity})[view]?.() || overview();}
function authPasswordInput(name,label,auto='new-password'){
 return `<div class="field"><label for="${name}">${label}</label><div class="password-control"><input type="password" id="${name}" name="${name.includes('confirm')?'confirm_password':'password'}" autocomplete="${auto}" required minlength="10" maxlength="128"/><button type="button" data-action="toggle-password" data-target="${name}" aria-label="Show password">Show</button></div></div>`;
}
function login(){
 const notice=authNotice?`<div class="auth-notice" role="status">${esc(authNotice)}</div>`:'';
 const error=loginError?`<div class="errorbox" role="alert">${esc(loginError)}</div>`:'';
 const links=`<div class="auth-links"><button data-action="auth-screen" data-screen="signin">Sign in</button><button data-action="auth-screen" data-screen="signup">Create FPO account</button><button data-action="auth-screen" data-screen="forgot">Forgot password?</button></div>`;
 let title='Welcome back.',intro='Log in to your FPO manager or buyer workspace.',content='';
 if(authScreen==='signup'){
  title='Create your FPO account.';intro='Free local workspace. Verify your email before signing in.';
  content=`<form data-form="signup" class="auth-form">${field('fpo_name','FPO / collection centre name','text','','autocomplete="organization" minlength="3" maxlength="120" required')}${field('manager_name','Your full name','text','','autocomplete="name" minlength="2" maxlength="100" required')}${field('email','Work email address','email','','autocomplete="email" required')}${authPasswordInput('signup-password','Create password')}${authPasswordInput('signup-confirm','Confirm password')}<div class="password-hint">Use 10+ characters with uppercase, lowercase and a number.</div><button class="btn primary" type="submit">Create FPO account →</button></form>`;
 }else if(authScreen==='forgot'){
  title='Reset your password.';intro='Enter your registered FPO email to request a secure reset link.';
  content=`<form data-form="forgot" class="auth-form">${field('email','Account email','email','','autocomplete="email" required')}<button class="btn primary" type="submit">Request reset link →</button></form>`;
 }else if(authScreen==='verify'){
  title='Verify your email.';intro='This is a one-time verification link. It expires after 24 hours.';
  content=`<form data-form="verify" class="auth-form"><div class="field"><label for="verify-token">Verification token from your email link</label><input id="verify-token" name="token" value="${esc(initialAuth.get('token')||'')}" required autocomplete="off"/></div><button class="btn primary" type="submit">Verify my email →</button></form>`;
 }else if(authScreen==='reset'){
  title='Set a new password.';intro='Reset links expire after 30 minutes and can only be used once.';
  content=`<form data-form="reset-password" class="auth-form"><input type="hidden" name="token" value="${esc(initialAuth.get('token')||'')}"/>${authPasswordInput('reset-password','New password')}${authPasswordInput('reset-confirm','Confirm new password')}<button class="btn primary" type="submit">Update password →</button></form>`;
 }else if(authScreen==='resend'){
  title='Resend verification.';intro='Enter your FPO email to request another verification link.';
  content=`<form data-form="resend" class="auth-form">${field('email','FPO email','email','','autocomplete="email" required')}<button class="btn primary" type="submit">Request verification →</button></form>`;
 }else{
  content=`<form data-form="login" class="auth-form"><div class="field"><label for="login-email">Email</label><input type="email" name="username" id="login-email" autocomplete="username" placeholder="manager@example.com" required/></div><div class="field"><label for="login-password">Password</label><div class="password-control"><input type="password" name="password" id="login-password" autocomplete="current-password" placeholder="Enter your password" required/><button type="button" data-action="toggle-password" data-target="login-password" aria-label="Show password">Show</button></div></div><button class="btn primary" type="submit">Sign in securely →</button></form><div class="hint"><strong>Local demo accounts</strong><br>FPO Manager: manager@agrova.test / Agrova123!<br>Buyer: sauce@agrova.test / Buyer123!<div class="button-row"><button class="btn small" data-action="fill-login" data-login="manager">Fill manager demo</button><button class="btn small" data-action="fill-login" data-login="buyer">Fill buyer demo</button></div></div>`;
 }
 return `<div class="login-page"><section class="login-art"><div class="brand">${brand}</div><div><div class="eyebrow" style="color:#bed4ae">AGROVA • FARMER PRODUCER ORGANISATIONS</div><h1>Better harvests.<br>Clearer decisions.</h1><p>One place to register crops, recover compatible sales, fulfill shortages and keep every settlement accountable.</p><div class="auth-steps"><span>01 &nbsp; Manage produce</span><span>02 &nbsp; Recover stock</span><span>03 &nbsp; Verify settlement</span></div></div><div class="text-xs" style="color:#aec6b3">TEAM INNOVATRIX · V3.1 Farmer Connect · Prototype</div></section><section class="login-form"><div class="brand">${brand}</div><span class="tagline">AGROVA V3.1 · FREE DEVELOPMENT</span><h2>${esc(title)}</h2><p class="lead">${esc(intro)}</p>${notice}${error}${content}${links}<p class="help">No real bank payments. Email is sent only when an email service is configured; otherwise the local server displays development links.</p></section></div><div class="toasts" id="toasts"></div>`;
}
function field(name,label,type='text',value='',attrs='') {return `<div class="field"><label for="f-${name}">${esc(label)}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></div>`;}
function sel(name,label,options,chosen,attrs=''){return `<div class="field"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}" ${attrs}>${options.map(([value,title])=>`<option value="${esc(value)}" ${String(value)===String(chosen)?'selected':''}>${esc(title)}</option>`).join('')}</select></div>`;}
function modalHTML(){const {type,id}=modal;let title='',desc='',inner='';const gradeOptions=['A','B','C'].map(x=>[x,'Grade '+x]);const safetyOptions=[['cleared','Safety cleared'],['pending','Pending inspection'],['hold','Safety hold']];
 if(type==='farmer'){title='Register farmer';desc='A manager creates a farmer profile. Farmer self-login is not implemented yet.';inner=`<form data-form="create-farmer">${field('name','Farmer full name','text','','required maxlength="120" autocomplete="name"')}${field('phone','Mobile number (optional)','tel','','inputmode="tel" pattern="\\+?[0-9]{10,15}" placeholder="9876543210"')}<div class="note">Phone numbers are stored privately in this FPO workspace. Do not add real farmer data to the public demo.</div><button class="btn primary" type="submit">Register farmer →</button></form>`;}
 if(type==='passport'){const l=lotById(id);const orig=(state.original_allocations||[]).filter(a=>a.lot_id===id);const rec=state.offers.filter(o=>o.lot_id===id);const source=(state.suppliers||[]).find(q=>q.received_lot_id===id);title='Digital quality passport — '+l.id;desc='Internal FPO record, not government certification or independent testing.';inner=`<div class="passport"><div class="eyebrow">INTERNAL TRACEABILITY · ${esc(l.id)}</div><h3>${esc(l.crop)} · ${esc(l.farmer)}</h3><div class="kv"><span>Inspected quantity</span><strong>${kg(l.quantity_kg)} kg</strong></div><div class="kv"><span>Inspection grade</span>${chip('Grade '+l.grade)}</div><div class="kv"><span>Safety status</span>${chip(l.safety,l.safety==='cleared'?'':'warn')}</div><div class="kv"><span>Record revision</span><strong>${l.version}</strong></div><div class="kv"><span>Current uncommitted stock</span><strong>${kg(available(l))} kg</strong></div>${source?`<div class="note">Sourced from ${esc(source.supplier_name)} via ${esc(source.id)}. Source confirmation was simulated; receiving inspection entered by manager.</div>`:''}<h4>Linked recovery reservations</h4>${rec.map(o=>`<div class="help">${esc(o.id)} · ${kg(o.quantity_kg)} kg · ${esc(o.status)}</div>`).join('')||'<div class="help">None yet</div>'}<h4 style="margin-top:12px">Linked original buyer allocations</h4>${orig.map(a=>`<div class="help">${esc(a.id)} · ${kg(a.quantity_kg)} kg · ${esc(a.status)}</div>`).join('')||'<div class="help">None yet</div>'}<div class="note warning">This internal passport proves only what was entered and tracked by the prototype, not actual food safety compliance.</div></div><button class="btn primary" data-action="close">Close passport</button>`;}
 if(type==='source-quote'){title='Add partner sourcing quotation';desc='Manual quote, not a live supplier discovery API. A confirmation and physical inspection are required before inventory changes.';const originals=state.orders.filter(o=>o.is_original);const o=originals[0];inner=`<form data-form="source-create">${sel('original_order_id','Original buyer order',originals.map(x=>[x.id,x.buyer_name+' · Grade '+x.grade]),o?.id)}${field('supplier_name','Partner FPO or supplier','text','','required')}${field('location','Supply location','text','Delhi NCR','required')}${field('crop','Produce','text',o?.crop||'Tomatoes','required')}<div class="fields-grid">${sel('grade','Offered grade',gradeOptions,o?.grade||'A')}${field('offered_kg','Offered quantity (kg)','number',shortage(o)||25,'min="0.001" step="0.001" required')}${field('rate_inr','Source price (₹/kg)','number',21,'min="0" step="0.01" required')}${field('transport_inr','Transport estimate (₹)','number',50,'min="0" step="0.01" required')}${field('handling_inr','Handling estimate (₹)','number',10,'min="0" step="0.01" required')}</div><button class="btn primary">Save quote →</button></form>`;}
 if(type==='source-receive'){const q=state.suppliers.find(x=>x.id===id);title='Receive & inspect partner supply';desc=q.supplier_name+' · '+kg(q.offered_kg)+' kg confirmed in the demo. Receiving quality is independently verified by the manager.';inner=`<form data-form="source-receive" data-id="${id}">${field('received_kg','Actual received weight (kg)','number',q.offered_kg,`min="0.001" max="${q.offered_kg}" step="0.001" required`)}<div class="fields-grid">${sel('grade','Inspected grade',gradeOptions,q.grade)}${sel('safety','Safety inspection',safetyOptions,'cleared')}</div><div class="note warning">Received Grade A, safety-cleared tomatoes can help cover FreshMart. Wrong grade or safety hold creates a separate lot but does not resolve its shortage.</div><button class="btn primary">Record receiving inspection</button></form>`;}
 if(type==='lot'){title='Add farmer lot';desc='New data changes eligibility and dashboard totals immediately.';inner=`<form data-form="create-lot">${(state.farmers||[]).length?sel('farmer_id','Registered farmer',state.farmers.map(f=>[f.id,f.name+' · '+f.id]),state.farmers[0].id,'required'):state.is_demo?field('farmer','Farmer name','text','','required maxlength="140"'):'<div class="note warning">Register a farmer first in the Farmers page.</div>'}${field('crop','Produce / crop','text','Tomatoes','required')}${field('quantity_kg','Received quantity (kg)','number','40','step="0.001" min="0.001" required')}<div class="fields-grid">${sel('grade','Inspection grade',gradeOptions,'B')}${sel('safety','Safety clearance',safetyOptions,'cleared')}</div><button class="btn primary" type="submit" ${(state.farmers||[]).length||state.is_demo?'':'disabled'}>Create lot</button></form>`;}
 if(type==='edit-lot'){const l=lotById(id);title=`Inspect ${l.id}`;desc=reservedForLot(l.id)?'Reserved/delivered lots are locked against silent changes to grade or safety.':'Update inspection and rerun eligibility.';inner=`<form data-form="edit-lot" data-id="${id}"><strong>${esc(l.farmer)} · ${esc(l.crop)}</strong>${field('quantity_kg','Total lot quantity (kg)','number',l.quantity_kg,`step="0.001" min="${Math.max(0.001,reservedForLot(l.id))}" required`)}<div class="fields-grid">${sel('grade','Grade',gradeOptions,l.grade)}${sel('safety','Safety status',safetyOptions,l.safety)}</div><div class="note">${kg(reservedForLot(l.id))} kg is reserved or already delivered. Cannot reduce the lot below this quantity.</div><button class="btn primary" type="submit">Save inspection revision</button></form>`;}
 if(type==='order'){title='Add buyer order';desc='Record a new original purchase order or recovery buyer. Supply must match grade, safety and available stock.';inner=`<form data-form="create-order">${sel('order_type','Order type',[['original','Original buyer commitment'],['recovery','Alternative recovery buyer']],'original')}${field('buyer_name','Buyer / company','text','New Processing Co','required')}${field('buyer_id','Buyer ID (lowercase, e.g. newprocessing)','text','newprocessing','required pattern="[a-z0-9_-]+"')}${field('crop','Crop','text','Tomatoes','required')}<div class="fields-grid">${sel('grade','Required grade',gradeOptions,'B')}${field('quantity_kg','Maximum demand (kg)','number','20','min="0.001" step="0.001" required')}${field('price_inr','Agreed rate (₹/kg)','number','18','min="0" step="0.01" required')}${sel('availability','Availability',[['accepting','Accepting offers'],['paused','Not accepting']],'accepting')}${field('transport_inr','Estimated transport cost (₹)','number',35,'min="0" step="0.01"')}${field('handling_inr','Estimated handling cost (₹)','number',5,'min="0" step="0.01"')}</div><div class="note">New buyer IDs have no login account by default. Manager may use clearly labelled demo acceptance, or use existing SauceWorks/FreshMart accounts.</div><button class="btn primary">Create buyer order</button></form>`;}
 if(type==='case'){title='Open recovery case';desc='Connect an inspected lot with an original buyer that cannot fully use it.';const original=state.orders.filter(o=>o.is_original);inner=`<form data-form="create-case">${sel('lot_id','Affected lot',state.lots.map(l=>[l.id,`${l.id} · ${l.farmer} · ${kg(l.quantity_kg)} kg Grade ${l.grade}`]),state.lots.find(l=>l.grade!=='A')?.id||state.lots[0]?.id)}${sel('original_order_id','Original order',original.map(o=>[o.id,`${o.id} · ${o.buyer_name} · Grade ${o.grade}`]),original[0]?.id)}<button class="btn primary">Create recovery case</button></form>`;}
 if(type==='offer'){const ctx=getContext();title='Send recovery offer';desc='Proposal only. Stock is not reserved until buyer acceptance and manager confirmation.';const eligibleOptions=state.orders.filter(o=>!o.is_original&&feasible(ctx.lot,o)>0);inner=eligibleOptions.length?`<form data-form="create-offer">${sel('order_id','Compatible buyer',eligibleOptions.map(o=>[o.id,`${o.buyer_name} · ${kg(feasible(ctx.lot,o))} kg max · ${rs(o.price_paise)}/kg`]),eligibleOptions[0].id)}${field('quantity_kg','Offer quantity (kg)','number',feasible(ctx.lot,eligibleOptions[0]),'min="0.001" step="0.001" required')}<div class="note">Buyer must accept. Manager must separately reserve stock. Backend checks latest availability atomically.</div><button class="btn primary">Send buyer offer →</button></form>`:'<div class="empty">No buyer is currently compatible. Change requirements or add a buyer order.</div>';}
 if(type==='delivery'){const o=offerById(id);title='Record delivery inspection';desc=`${o.id} · ${kg(o.quantity_kg)} kg reserved. The entire reservation is delivered in this prototype.`;inner=`<form data-form="create-delivery" data-id="${id}">${field('delivered_kg','Delivered quantity (kg)','number',o.quantity_kg,'step="0.001" min="0.001" readonly required')}<div class="fields-grid">${field('accepted_kg','Accepted (kg)','number',Math.max(0,o.quantity_kg-2),'step="0.001" min="0" required')}${field('rejected_kg','Rejected (kg)','number',Math.min(2,o.quantity_kg),'step="0.001" min="0" required')}</div><div class="field"><label>Inspection note</label><textarea name="inspection_note" placeholder="Condition, grade, custody of rejected portion, etc.">Provisional inspection; rejected goods held for reinspection.</textarea></div><div class="note">Accepted + rejected must equal delivered. Rejected produce is not automatically made available for resale.</div><button class="btn primary">Record inspection →</button></form>`;}
 if(type==='upload'){title='Upload evidence';desc='Attach a delivery receipt or buyer statement to this delivery. Files are kept private on the server.';inner=`<form data-form="upload" data-id="${id}">${sel('kind','Document type',[['inspection','Delivery inspection receipt'],['buyer','Buyer settlement statement']],'buyer')}<div class="field"><label for="upload-file">Choose file (up to 5 MB)</label><input type="file" id="upload-file" name="file" accept=".txt,.pdf,.png,.jpg,.jpeg,.webp,text/plain,application/pdf,image/*" required></div><div class="note">${state.ai_enabled?'Gemini enabled. After uploading, run extraction, then verify each field.':'Gemini key is not configured. TXT files have honest offline text parsing; PDF/images can be manually verified.'}</div><button class="btn primary">Upload document</button></form>`;}
 if(type==='verify'){const doc=state.deliveries.flatMap(d=>d.evidence).find(d=>d.id===id);const proposed=doc.verified||doc.proposed||{};const d=state.deliveries.find(d=>d.id===doc.delivery_id);title='Verify extracted fields';desc=`${doc.id} · ${doc.file_name} · ${doc.kind==='inspection'?'Inspection':'Buyer statement'} source. Compare every value with the real document before confirming.`;inner=`<form data-form="verify" data-id="${id}"><div class="note ${doc.proposed?'':'warning'}">${doc.proposed?`Suggested extraction: ${esc(doc.engine)}. Manager confirmation is required.`:'No extraction available. Manually enter the actual document values; do not guess.'}</div><div class="fields-grid">${field('accepted_kg','Accepted quantity (kg) *','number',proposed.accepted_kg??'','step="0.001" min="0" required')}${field('rejected_kg','Rejected quantity (kg)','number',proposed.rejected_kg??'','step="0.001" min="0"')}${field('delivered_kg','Delivered quantity (kg)','number',proposed.delivered_kg??'','step="0.001" min="0"')}${field('rate_inr','Document rate (₹/kg)','number',proposed.rate_inr??'','step="0.01" min="0"')}${field('deductions_inr','Document deductions (₹)','number',proposed.deductions_inr??0,'step="0.01" min="0"')}${field('lot_ref','Lot reference','text',proposed.lot_ref??'')}</div>${field('source_reference','Source line / page / explanation','text',proposed.source_reference??'','maxlength="220"')}<p class="help">Delivery recorded ${kg(d.delivered_kg)} kg. Accepted quantity cannot exceed delivered quantity. Agreed rate comes from the accepted offer, not AI.</p><button class="btn primary">Confirm verified fields</button></form>`;}
 if(type==='review'){const d=state.deliveries.find(d=>d.id===id);title='Record human decision';desc='Document discrepancies are evidence for review, not an automatic fraud or payment decision.';inner=`<form data-form="review" data-id="${id}">${sel('decision','Reviewer action',[['more_evidence','Request more evidence'],['inspection_basis','Accept inspection basis'],['buyer_basis','Accept buyer statement basis']],'more_evidence')}<div class="field"><label>Required justification</label><textarea name="note" required minlength="10" placeholder="What did you verify? Which document supports the decision?"></textarea></div><div class="note warning">No transfer is sent. Reviewed settlements remain UNPAID. All decisions are audit logged.</div><button class="btn primary">Record decision</button></form>`;}
 return `<div class="modal-backdrop" data-action="close-outside"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="rowbetween" style="margin-bottom:16px"><div><h2>${esc(title)}</h2></div><button class="modal-close" aria-label="Close" data-action="close">×</button></div><p class="modal-desc">${esc(desc)}</p>${inner}</div></div>`;}
function render(){const root=$('#app');root.innerHTML=state?chrome():login();renderToast();}
async function work(fn,success){if(loading)return;loading=true;try{await fn();modal=null;await refresh();if(success)notify(success);}catch(e){notify(e.message||'Operation failed',true);}finally{loading=false;}}
function dataFrom(form){return Object.fromEntries(new FormData(form).entries());}
document.addEventListener('click',async e=>{
 const btn=e.target.closest('[data-action]');if(!btn)return;const action=btn.dataset.action,id=btn.dataset.id;
 if(action==='mobile-more'){mobileMenu=!mobileMenu;render();return;}
 if(action==='toggle-password'){const node=document.getElementById(btn.dataset.target);if(node){node.type=node.type==='password'?'text':'password';btn.textContent=node.type==='password'?'Show':'Hide';btn.setAttribute('aria-label',node.type==='password'?'Show password':'Hide password');}return;}
 if(action==='auth-screen'){authScreen=btn.dataset.screen;authNotice='';loginError='';if(location.protocol==='http:'||location.protocol==='https:')history.replaceState({},'',location.pathname);render();return;}
 if(action==='close-outside'){if(e.target===btn){modal=null;render();}return;}
 if(action==='close'){modal=null;render();return;}
 if(action==='view'){view=btn.dataset.view;mobileMenu=false;modal=null;render();window.scrollTo(0,0);return;}
 if(action==='open'){modal={type:btn.dataset.modal,id};render();return;}
 if(action==='fill-login'){$('#login-email').value=btn.dataset.login==='buyer'?'sauce@agrova.test':'manager@agrova.test';$('#login-password').value=btn.dataset.login==='buyer'?'Buyer123!':'Agrova123!';return;}
 if(action==='logout'){await work(async()=>{await request('/auth/logout','POST');state=null;view='overview';},'Signed out.');return;}
 if(action==='reset'){if(!confirm('Reset all demo lots, offers, deliveries, evidence references and audit events? This cannot be undone.'))return;await work(()=>request('/demo/reset','POST'),'Demo data reset.');view='overview';return;}
 if(action==='speak'){const text=$('#hindi-explanation')?.textContent;if(text&&'speechSynthesis' in window){speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='hi-IN';u.rate=.9;speechSynthesis.speak(u);}else notify('Hindi text-to-speech is not supported in this browser.',true);return;}
 if(action==='demo-accept')return work(()=>request(`/offers/${id}/demo-accept`,'POST'),'Simulated buyer acceptance recorded.');
 if(action==='buyer-accept')return work(()=>request(`/offers/${id}/accept`,'POST'),'Offer accepted as buyer.');
 if(action==='reserve')return work(()=>request(`/offers/${id}/reserve`,'POST'),'Reserved with an atomic inventory check.');
 if(action==='cancel'){if(confirm('Cancel this offer and release any reservation?'))return work(()=>request(`/offers/${id}/cancel`,'POST'),'Offer cancelled.');return;}
 if(action==='source-confirm'){if(!confirm('Demo only: mark partner quotation as confirmed? No real supplier is contacted.'))return;return work(()=>request(`/sourcing/${id}/confirm`,'POST',{}),'Illustrative supplier confirmation recorded. Receive and inspect next.');}
 if(action==='source-cancel')return work(()=>request(`/sourcing/${id}/cancel`,'POST',{}),'Supplier quote cancelled.');
 if(action==='auto-allocate')return work(()=>request('/original/auto-allocate','POST',{order_id:id}),'Eligible stock reserved for original order. Dispatch/acceptance still pending.');
 if(action==='original-dispatch')return work(()=>request(`/original/allocations/${id}/dispatch`,'POST',{}),'Original stock marked dispatched; not yet buyer accepted.');
 if(action==='original-cancel')return work(()=>request(`/original/allocations/${id}/cancel`,'POST',{}),'Original allocation released.');
 if(action==='extract')return work(()=>request(`/evidence/${id}/extract`,'POST'),'Fields proposed. Open Verify fields to confirm against the document.');
});
document.addEventListener('change',e=>{if(e.target.id==='case-switch'){selectedCaseId=e.target.value;render();}if(e.target.id==='economics-lot'){comparisonLotId=e.target.value;render();}});
document.addEventListener('submit',async e=>{
 const f=e.target.closest('form[data-form]');if(!f)return;e.preventDefault();const type=f.dataset.form,vals=dataFrom(f),id=f.dataset.id;
 const fNumber=['quantity_kg','price_inr','transport_inr','handling_inr','offered_kg','received_kg','delivered_kg','accepted_kg','rejected_kg','rate_inr','deductions_inr'];for(const key of fNumber)if(key in vals)vals[key]=vals[key]===''?null:Number(vals[key]);
 if(type==='signup'){
  const password=vals.password,confirmation=vals.confirm_password;
  if(password!==confirmation){loginError='Passwords do not match.';authNotice='';render();return;}
  try{const r=await request('/auth/register','POST',{fpo_name:vals.fpo_name,manager_name:vals.manager_name,email:vals.email,password,confirm_password:confirmation});loginError='';authNotice=r.message;authScreen='resend';render();}catch(err){loginError=err.message;render();}return;
 }
 if(['forgot','resend','verify','reset-password'].includes(type)){
  const route={forgot:'/auth/forgot',resend:'/auth/resend',verify:'/auth/verify','reset-password':'/auth/reset'}[type];
  if(type==='reset-password'&&vals.password!==vals.confirm_password){loginError='Passwords do not match.';render();return;}
  try{const r=await request(route,'POST',vals);loginError='';authNotice=r.message||'Request processed.';if(type==='verify'||type==='reset-password'){authScreen='signin';if(location.protocol==='http:'||location.protocol==='https:')history.replaceState({},'',location.pathname);}render();}catch(err){loginError=err.message;render();}return;
 }
 if(type==='create-farmer')return work(()=>request('/farmers','POST',vals),'Farmer registered. You can now create their crop lot.');
 if(type==='login'){try{await request('/auth/login','POST',vals);loginError='';authNotice='';await refresh();}catch(e){loginError=e.message;render();}return;}
 if(type==='source-create')return work(()=>request('/sourcing/quotes','POST',vals),'Partner quote recorded. No stock added until inspection.');
 if(type==='source-receive')return work(()=>request(`/sourcing/${id}/receive`,'POST',vals),'Received supply added as inspected lot; original coverage recalculated.');
 if(type==='create-lot')return work(()=>request('/lots','POST',vals),'Lot created. Eligibility updated.');
 if(type==='edit-lot')return work(()=>request(`/lots/${id}`,'PATCH',vals),'Inspection revision saved.');
 if(type==='create-order')return work(()=>request('/orders','POST',vals),'Buyer order added.');
 if(type==='edit-order')return work(()=>request(`/orders/${id}`,'PATCH',vals),'Buyer matching recomputed.');
 if(type==='create-case')return work(async()=>{const result=await request('/cases','POST',vals);selectedCaseId=result.id;view='recovery';},'Recovery case created.');
 if(type==='create-offer')return work(()=>request('/offers','POST',{...vals,case_id:caseInfo().id}),'Buyer offer sent; not yet reserved.');
 if(type==='create-delivery')return work(async()=>{const result=await request('/deliveries','POST',{...vals,offer_id:id});window.__deliveryChoice=result.id;view='settlement';},'Inspection recorded. Attach evidence next.');
 if(type==='upload')return work(async()=>{const file=f.querySelector('input[type=file]').files[0];if(!file)throw Error('Choose a file.');if(file.size>5*1024*1024)throw Error('Maximum evidence file size is 5 MB.');let mime=file.type||({'txt':'text/plain','pdf':'application/pdf','png':'image/png','jpg':'image/jpeg','jpeg':'image/jpeg','webp':'image/webp'}[file.name.split('.').pop().toLowerCase()]);if(!mime)throw Error('Unsupported file. Use TXT, PDF or image.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));await request('/evidence','POST',{delivery_id:id,kind:vals.kind,file_name:file.name,mime,base64:btoa(binary)});},'Evidence uploaded. Extract and confirm its fields.');
 if(type==='verify')return work(()=>request(`/evidence/${id}/verify`,'POST',vals),'Verified data saved; reconciliation recalculated.');
 if(type==='review')return work(()=>request('/reviews','POST',{...vals,delivery_id:id}),'Human decision recorded; payment remains unpaid.');
});
refresh();
